// Calcula las páginas de resultados de cada escuela a partir de su primera página.
const busquedas = $('Preparar búsqueda').all();
const salto = 25;
const out = [];

$input.all().forEach((item, i) => {
  const b = busquedas[i]?.json;
  if (!b) return;
  const html = String(item.json.data ?? '');

  const regex = /<span[^>]*class="[^"]*\bep_search_number\b[^"]*"[^>]*>(.*?)<\/span>/gis;
  const numeros = [];
  let m;
  while ((m = regex.exec(html)) !== null) {
    const n = parseInt(m[1].replace(/<[^>]+>/g, '').replace(/[^\d]/g, ''), 10);
    if (!Number.isNaN(n)) numeros.push(n);
  }
  const total = numeros[2] ?? 0;
  const paginasTotales = Math.ceil(total / salto);
  const fin = b.max_paginas > 0 ? Math.min(paginasTotales, b.pagina_inicio + b.max_paginas) : paginasTotales;

  for (let p = b.pagina_inicio; p < fin; p++) {
    out.push({ json: {
      escuela: b.escuela, pagina: p, offset: p * salto,
      url: b.base + (p * salto), total_tfgs: total, paginas_totales: paginasTotales
    }});
  }
});

return out;

const hrefs = $input.first().json.href|| [];
const urlsFiltradas = [];

const reBase = /^https:\/\/oa\.upm\.es\/\d+\/$/;

for (const url of hrefs) {
  if (reBase.test(url)) {
    urlsFiltradas.push(url);
  }
}

const out = Array.from(new Set(urlsFiltradas));

return out.map(u => ({ json: { url: u } }));

// Quita duplicados y descarta los TFG que ya están en Postgres.
// Sustituye a los nodos 'Encontrado' + 'Eliminar encontrado y posteriores'
// del workflow de actualización original.
const existentes = new Set(
  $('IDs existentes').all().map(i => String(i.json.id ?? '')).filter(Boolean)
);
const vistos = new Set();
const out = [];
for (const item of $input.all()) {
  const url = item.json.url;
  if (!url) continue;
  const id = (url.match(/oa\.upm\.es\/(\d+)/) || [])[1];
  if (!id || existentes.has(id) || vistos.has(id)) continue;
  vistos.add(id);
  out.push({ json: { url } });
}
return out;

const data = { ...$json };

const abs = Array.isArray(data.abstract)
  ? data.abstract.join(' ')
  : String(data.abstract || '').trim();


const parts = abs.split(/\n*\s*ABSTRACT\s*\n*/i);

const abstract_spanish = parts[0]?.trim() || '';
const abstract_english = parts[1]?.trim() || '';

delete data.abstract;
data.abstract_spanish = abstract_spanish;
data.abstract_english = abstract_english;

return data;

const arr = v => Array.isArray(v) ? v.filter(x => x != null && String(x).trim() !== '') : (v == null ? [] : [v]);
const first = v => arr(v)[0] ?? '';

const normalizeText = (s, max = 300000) => {
  let t = String(s ?? '');

  t = t.replace(/\r\n?/g, '\n');
  t = t.replace(/[ \t]+\n/g, '\n');
  t = t.replace(/\n[ \t]+/g, '\n');
  t = t.replace(/\n{2,}/g, '\n');
  t = t.replace(/\n{3,}/g, '\n');
  t = t.replace(/([^\n])\n(?!\n)/g, '$1 ');

  return t
    .normalize('NFC')
    .replace(/[^\S\n\t]+/g, ' ')                  
    .replace(/[\u0000-\u0008\u000B-\u001F\u007F]/g, ' ')
    .replace(/^\s*(abstract|resumen)\s*[:\-–—]?\s*/i, '')
    .replace(/^[\s:;,\-–—]+/, '')                 
    .trim()
    .slice(0, max);
};

const id =(first($json.document_url).match(/oa\.upm\.es\/(\d+)/)?.[1] ?? '');

const url    = id ? `https://oa.upm.es/${id}` : '';
const docUrl = first($json.document_url);

const title = normalizeText($json.title || $json['título']);

const rawEs = first($json.abstract_spanish) || first($json.abstract_es);
const rawEn = first($json.abstract_english) || first($json.abstract_en);

const absES = normalizeText(rawEs) || null;
const absEN = normalizeText(rawEn) || null;

const p = [
  id,
  title,
  JSON.stringify(arr($json.creators_name)),
  JSON.stringify(arr($json.creators_id)),
  JSON.stringify(arr($json.contributors_name)),
  JSON.stringify(arr($json.contributors_id)),
  JSON.stringify(arr($json.subjects)),
  JSON.stringify(arr($json.ods)),
  first($json.date) || null,
  url || null,
  docUrl || null,
  first($json.dc_publisher) || null,
  JSON.stringify(arr($json.dc_rights)),
  Boolean($json.private),
  absES,
  absEN
];

return { json: { params: p } };

const p = $json.params;

if (!Array.isArray(p) || p.length < 16) {
  throw new Error('Faltan parámetros: esperaba 16 posiciones en `params`.');
}

const obj = {
  id: p[0],
  title: p[1] || '',
  creators_name: JSON.parse(p[2]  || '[]'),
  creators_id: JSON.parse(p[3]  || '[]'),
  contributors_name: JSON.parse(p[4] || '[]'),
  contributors_id: JSON.parse(p[5]  || '[]'),
  subjects: JSON.parse(p[6]  || '[]'),
  ods: JSON.parse(p[7]  || '[]'),
  date: p[8] || null,
  url: p[9] || null,
  document_url: p[10] || null,
  dc_publisher: p[11] || null,
  dc_rights: JSON.parse(p[12] || '[]'),
  private: Boolean(p[13]),
  abstract_es: p[14] || '',
  abstract_en: p[15] || '',
};

const list = a => (Array.isArray(a) ? a : []).filter(Boolean).join(', ');
const year = (obj.date || '').slice(0, 4);

const embed_text = [
  obj.title && `[TITULO] ${obj.title}`,
  obj.abstract_es && `[ABSTRACT_ES] ${obj.abstract_es}`,
  obj.abstract_en && `[ABSTRACT_EN] ${obj.abstract_en}`,
  obj.subjects?.length && `[ASIGNATURAS] ${list(obj.subjects)}`,
  obj.ods?.length && `[ODS] ${list(obj.ods)}`,
  year && `[FECHA] ${year}`,
].filter(Boolean).join(' ');

const payload = {
  id: obj.id,
  url: obj.url,
  url_pdf: obj.document_url,
  titulo: obj.title,
  autor: obj.creators_name,
  autor_id: obj.creators_id,
  director: obj.contributors_name,
  director_id: obj.contributors_id,
  asignaturas: obj.subjects,
  ods: obj.ods,
  fecha: obj.date,
  institucion: obj.dc_publisher,
  derechos: obj.dc_rights,
  privado: obj.private,
};

return {
  json: {
    embed_text,
    payload
  }
};

// Prepara la búsqueda en el OA.
// Carga: campo "escuela" de Config carga. Vacío = toda la UPM; con un código = solo esa escuela.
// Actualización: campo "escuelas" de Config actualización, códigos separados por comas. Vacío = toda la UPM.
const leerConfig = (nombre) => {
  try { return $(nombre).first().json; } catch (e) { return null; }
};
const cfg = leerConfig('Config actualización') || leerConfig('Config carga') || {};
let escuelas = String(cfg.escuelas ?? cfg.escuela ?? '')
  .split(',').map(s => s.trim()).filter(Boolean);
if (escuelas.length === 0) escuelas = [''];   // '' = toda la UPM

const base = (codigo) =>
  'https://oa.upm.es/cgi/search/archive/advanced?order=-date%2Fcreators_name%2Ftitle&exp=0%7C1%7C-date%2Fcreators_name%2Ftitle%7Carchive%7C-%7C' +
  (codigo ? 'institution%3Ainstitution%3AANY%3AEQ%3A' + encodeURIComponent(codigo) + '%7C' : '') +
  'type%3Atype%3AANY%3AEQ%3Aother%7C-%7Ceprint_status%3Aeprint_status%3AANY%3AEQ%3Aarchive%7Cmetadata_visibility%3Ametadata_visibility%3AANY%3AEQ%3Ashow&screen=Search&_action_search=1&search_offset=';

return escuelas.map(escuela => ({
  json: {
    escuela: escuela || 'toda la UPM',
    base: base(escuela),
    url_primera: base(escuela) + '0',
    pagina_inicio: Math.max(0, Number(cfg.pagina_inicio) || 0),
    max_paginas: Number(cfg.max_paginas) || 0
  }
}));
